我在用 C++26 反射做练习，写了几个小例子，主要通过 Godbolt 来验证和测试。

获取用户定义的成员函数名， 不包括模版  https://godbolt.org/z/dbazEsPr8

#include &lt;meta&gt;#include &lt;iostream&gt;using namespace std::meta;template &lt;typename T&gt;consteval auto get_member_function_names() &#123;    auto helper = [] consteval &#123;        return members_of(^^T, access_context::unchecked()) | std::views::filter([](auto m) &#123;                   return is_function(m) &amp;&amp; !is_constructor(m) &amp;&amp; !is_destructor(m) &amp;&amp; is_user_provided(m);               &#125;) |               std::views::transform(display_string_of) | std::ranges::to&lt;std::vector&gt;();    &#125;;    auto names = helper(); // helper() 的结果没有办法用constexpr， names.size() 无法编译， 只能用 helper().size()    std::array&lt;std::string_view, helper().size()&gt; ret;    std::ranges::copy(names, ret.begin());    return ret;&#125;struct X &#123;    char a;    int b;    double c;    void f1(int) &#123;&#125;    void f2() &#123;&#125;&#125;;int main() &#123;    for (const auto names : get_member_function_names&lt;X&gt;()) &#123;        std::cout &lt;&lt; names &lt;&lt; std::endl;    &#125;&#125;


批量输出meta function的结果 https://godbolt.org/z/c1xxbn7Wx

#include &lt;meta&gt;#include &lt;print&gt;using namespace std::meta;template &lt;info metafunc, info meta&gt;consteval auto get_info() &#123;    return [:metafunc:](meta);&#125;template &lt;info meta, info... funcs&gt;void print_info() &#123;    template for (constexpr auto f : &#123;^^display_string_of, funcs...&#125;) &#123;        constexpr auto name = display_string_of(f);        constexpr auto val = get_info&lt;f, meta&gt;();        using val_type = std::remove_cvref_t&lt;decltype(val)&gt;;        std::println(&quot;&#123;&#125;: &#123;&#125;&quot;, name, val);    &#125;&#125;consteval auto type_name_of(info v) &#123; return display_string_of(type_of(v)); &#125;int main() &#123;    print_info&lt;^^int, ^^is_type, ^^is_template, ^^is_class_member&gt;();    std::println();    int a = 0;    print_info&lt;^^a, ^^is_type, ^^identifier_of, ^^size_of, ^^type_name_of&gt;();    return 0;&#125;


获取enum的名称和数值 https://godbolt.org/z/n1vhGEKEK

#include &lt;array&gt;#include &lt;iostream&gt;#include &lt;meta&gt;template &lt;typename E&gt;struct enum_item &#123;    std::string_view name;    E value;&#125;;template &lt;typename E&gt;consteval auto get_enum_data() &#123;    constexpr auto enumerators = std::define_static_array(std::meta::enumerators_of(^^E));    std::array&lt;enum_item&lt;E&gt;, enumerators.size()&gt; result;    int k = 0;    template for (constexpr auto mem : enumerators) &#123;        result[k++] = enum_item&lt;E&gt;&#123;std::meta::identifier_of(mem), std::meta::extract&lt;E&gt;(mem)&#125;;    &#125;    return result;&#125;enum MyEnum &#123; x, y, e = -1, z = 99 &#125;;int main() &#123;    std::cout &lt;&lt; &quot;members of &quot; &lt;&lt; std::meta::identifier_of(^^MyEnum) &lt;&lt; &#x27;\n&#x27;;    for (auto x : get_enum_data&lt;MyEnum&gt;()) &#123;        std::cout &lt;&lt; &quot;  &quot; &lt;&lt; x.name &lt;&lt; &quot; = &quot; &lt;&lt; (long)x.value &lt;&lt; &#x27;\n&#x27;;    &#125;&#125;


判断结构体是否相等 https://godbolt.org/z/13bKh8njf

#include &lt;meta&gt;struct CompareEqual &#123;    template &lt;typename Self&gt;    constexpr bool operator==(this const Self &amp;self, const Self &amp;other) noexcept &#123;        template for (constexpr auto field : std::define_static_array(std::meta::nonstatic_data_members_of(                          ^^Self, std::meta::access_context::unchecked()))) &#123;            if (self.[:field:] != other.[:field:]) &#123;                return false;            &#125;        &#125;        return true;    &#125;&#125;;struct A : CompareEqual &#123;    int a;    int b;&#125;;int main() &#123;    constexpr A a&#123;.a = 10, .b = 2&#125;;    constexpr A b&#123;.a = 1, .b = 2&#125;;    constexpr A c&#123;.a = 10, .b = 2&#125;;    static_assert(a == c);    static_assert(a != b);    return 0;&#125;

可以在参数列表之后使用引用限定符来指定this对象的左值与右值属性;

若引用限定符为&amp;,则表明this对象指向着左值对象
若引用限定符为&amp;&amp;,则表明this对象指向着右值对象引用限定符语法点:
引用限定符必须同时出现在声明以及实现之后.
引用限定符必须出现在const限定符之后;如:

struct X &#123;	void foo() const &amp;; // 正确.	void bar() &amp; const; // 错误!&#125;;

若引用限定符用于重载;则所有同名函数要么都带有引用限定符;要么都不带有引用限定符;不然会编译出错

struct X &#123;    void foo() &amp; &#123;&#125; // 1    void foo() &amp;&amp; &#123;&#125;// 2&#125;;X x;x.foo(); // 调用 foo1(),X().foo(); // 调用 foo2();

众所周知，range for里的临时变量左值有问题
class Keeper &#123;    std::vector&lt;int&gt; data&#123;2, 3, 4&#125;;public:  ~Keeper() &#123; std::cout &lt;&lt; &quot;dtor\n&quot;; &#125;  auto&amp; items() &#123; return data; &#125;&#125;;Keeper GetKeeper() &#123;  return &#123;&#125;;&#125;void Use() &#123;  for(auto&amp; item : GetKeeper().items()) &#123;    std::cout &lt;&lt; item &lt;&lt; &#x27;\n&#x27;;  &#125;&#125;
上面的item是无效的引用
可以用引用限定符来改
class Keeper &#123;  std::vector&lt;int&gt; data&#123;2, 3, 4&#125;;public:  ~Keeper() &#123; std::cout &lt;&lt; &quot;dtor\n&quot;; &#125;  auto&amp; items() &amp; &#123; return data; &#125;  auto items() &amp;&amp; &#123; return std::move(data); &#125;&#125;;

注意这两个items后面的&amp;限定，两种限定约定了被调用的时候走左还是右值，如果是range for循环，就调用第二个items，救一下data的生命，就没问题了。
除了左值引用、右指引用， const volaile noexcept 都可以修饰成员函数， 表示对象被相应关键字修饰的时候，可以调用的成员函数， 这些关键字属于成员函数的类型的一部分 (noexcept 不能修饰对象， 只能修饰函数，表示函数不会抛出异常)

在 Python、Rust 等现代编程语言中，Self 类型是一个非常方便的特性。它允许我们在类定义中引用当前类的类型，无需重复写出类名。例如在 Python 中：
from typing import Selfclass MyClass:    def method(self) -&gt; Self:  # Self 直接表示 MyClass        return self

然而在 C++ 中，标准并没有提供原生的 Self 类型支持。我们可以通过一些方法实现 Self。
#include &lt;type_traits&gt;namespace SelfType &#123;template &lt;typename T&gt;struct Reader &#123;#if defined(__GNUC__) &amp;&amp; !defined(__clang__) // gcc 会出现告警，需要屏蔽#pragma GCC diagnostic push#pragma GCC diagnostic ignored &quot;-Wnon-template-friend&quot;#endif    friend auto adl_GetSelfType(Reader&lt;T&gt;);#if defined(__GNUC__) &amp;&amp; !defined(__clang__)#pragma GCC diagnostic pop#endif&#125;;template &lt;typename T, typename U&gt;struct Writer &#123;    friend auto adl_GetSelfType(Reader&lt;T&gt;) &#123; return U&#123;&#125;; &#125;&#125;;template &lt;typename T&gt;using Read = std::remove_pointer_t&lt;decltype(adl_GetSelfType(Reader&lt;T&gt;&#123;&#125;))&gt;;&#125; // namespace SelfType#define DEFINE_SELF                                                                                          \    struct _self_type_tag &#123;&#125;;                                                                                \    constexpr auto _self_type_helper()                                                                       \        -&gt; decltype(::SelfType::Writer&lt;_self_type_tag, decltype(this)&gt;&#123;&#125;, void());                           \    using Self = ::SelfType::Read&lt;_self_type_tag&gt;;// 不用重复类名， gcc clang msvc 都可以用class Test &#123;private:    DEFINE_SELF    static_assert(std::is_same_v&lt;Self, Test&gt;);&#125;;// clang 不能编译  invalid use of &#x27;this&#x27; outside of a non-static member function#define DEFINE_SELF2 \    typedef auto _self_fn() -&gt; decltype(*this); \    using self = std::remove_reference_t&lt;decltype(((_self_fn*)0)())&gt;;struct Foo &#123;    DEFINE_SELF2;&#125;;// 需要重复类名class Test2 &#123;private:    using Self = Test2;&#125;;// 用宏，只能在成员函数中使用#define SELF std::decay_t&lt;decltype(*this)&gt;

解释一下DEFINE_SELF_self_type_helper  的返回值推导让Writer 中定义友元函数 adl_GetSelfType， 返回类型是decltype(this)，即Test * （标准规定函数可以在一个类的友元声明中被定义，这种情况下该函数是类所在名字空间的一个函数，而不是类的成员函数）然后 Read 就是 adl_GetSelfType的返回类型去掉指针，即Test
